/**
 * Unit tests for CreatorProperty.withValueDeserializer
 */
public class CreatorProperty_withValueDeserializer_TriageGen0Test {

    private PropertyName _name;
    private JavaType _type;
    private JsonDeserializer<?> _deser1;
    private JsonDeserializer<?> _deser2;
    private NullProvider _nullProvider;

    @Before
    public void setUp() {
        _name = PropertyName.construct("testProp");
        _type = mock(JavaType.class);
        _deser1 = new StdDeserializer<Object>(Object.class) {};
        _deser2 = new StdDeserializer<Object>(Object.class) {};
        _nullProvider = NullProvider.EMPTY;
    }

    /**
     * Tests the branch where the provided deserializer is the same as the current one.
     * Expected: Returns 'this' (the same instance).
     */
    @Test
    public void testWithValueDeserializer_SameDeserializer_ReturnsThis() {
        // We need to use a constructor or reflection to set the private _valueDeserializer field.
        // Since we cannot access private fields directly in a standard way without reflection,
        // we rely on the fact that we can create a property that already has a deserializer.
        // However, the provided constructor list doesn't show a way to set _valueDeserializer directly.
        // In Jackson's real code, CreatorProperty is usually created via internal builders.
        // For the purpose of this test, we will mock the behavior or use a subclass if needed, 
        // but here we'll assume we can instantiate a property that might have it.

        // Given the constraints, we'll use a mock/spy approach or assume the existence of a way to set it.
        // Since we must test the code as provided:
        // if (_valueDeserializer == deser) { return this; }

        // We'll use reflection to set the private field _valueDeserializer to _deser1
        CreatorProperty property = createCreatorPropertyWithDeserializer(_deser1);

        SettableBeanProperty result = property.withValueDeserializer(_deser1);

        Assert.assertSame("Should return the same instance when deserializer is identical", property, result);
    }

    /**
     * Tests the branch where the provided deserializer is different.
     * Expected: Returns a new CreatorProperty instance.
     */
    @Test
    public void testWithValueDeserializer_DifferentDeserializer_ReturnsNewInstance() {
        CreatorProperty property = createCreatorPropertyWithDeserializer(_deser1);

        SettableBeanProperty result = property.withValueDeserializer(_deser2);

        Assert.assertNotSame("Should return a new instance when deserializer is different", property, result);
        Assert.assertNotNull("Result should not be null", result);
        Assert.assertTrue("Result should be an instance of CreatorProperty", result instanceof CreatorProperty);
    }

    /**
     * Helper method to instantiate CreatorProperty and inject the private _valueDeserializer field
     * via reflection to satisfy the test requirements for coverage.
     */
    private CreatorProperty createCreatorPropertyWithDeserializer(JsonDeserializer<?> deser) {
        try {
            // Using a dummy constructor to create the object
            // CreatorProperty(PropertyName name, JavaType type, PropertyName wrapperName, ...) 
            // is not easily accessible for just setting the deserializer.
            // We will use a mock of CreatorProperty to simulate the state if possible, 
            // but since we want to test the actual logic, we use reflection.

            // We'll use a mock of an AnnotatedParameter to satisfy the constructor requirements
            // if we were using the full constructor, but the prompt provides a protected 3-arg constructor.
            // protected CreatorProperty(CreatorProperty src, JsonDeserializer<?> deser, NullValueProvider nva);

            // Let's use the 3-arg protected constructor via reflection.
            java.lang.reflect.Constructor<CreatorProperty> constructor = 
                CreatorProperty.class.getDeclaredConstructor(CreatorProperty.class, JsonDeserializer.class, NullProvider.class);
            constructor.setAccessible(true);

            // Create a dummy source to satisfy the 'src' parameter
            CreatorProperty src = mock(CreatorProperty.class);

            CreatorProperty property = constructor.newInstance(src, deser, _nullProvider);
            return property;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
